function hwAutoSubmit(){
  var p = HW.prob;
  if (!p || !p.oj_url) return;
  stashProbCode();
  var pick = hwSubmitCode();
  if (!pick.code.trim()){
    toast("先写代码，或在「解析」里生成一份");
    return;
  }
  /* ★★ 提交是全产品唯一不可撤销、会写进外部 OJ 记录的动作。所以**每次都要确认**：
     把这一份代码钉在 HW.pendingSubmit 上，题面里展开一个确认块（不是弹层 ——
     弹层会把题面顶掉，用户点「取消」就回不来了）；确认后提交的就是钉住的那份，
     两次渲染之间页签一换也不会换掉交出去的东西。 */
  HW.pendingSubmit = { code: pick.code, from: pick.from };
  renderProblem();
  var el = document.querySelector ? document.querySelector(".subConfirm") : null;
  if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
}
/* 来源文案：传 from 就用传进来的（确认块要显示"钉住的那份"），不传按当前状态算 */
function hwFromText(from){
  if (from === "ai"){
    return aiFinalCodeIndex() > 0 ? "解析里 AI 修正后的代码" : "解析里 AI 写的那份代码";
  }
  if (from === "mine") return "测一测里你自己的代码";
  return "还没有代码";
}
function hwSubmitSrcText(){ return hwFromText(hwSubmitCode().from); }
/* 题面里的确认块：题目 + 来源 + 代码开头三行 + 两条后果 */
function hwSubmitConfirmHtml(){
  var pick = HW.pendingSubmit;
  if (!pick || !String(pick.code || "").trim()) return "";
  var lines = String(pick.code).split("\n");
  var head3 = lines.slice(0, 3).join("\n");
  var more = lines.length > 3 ? "\n…（共 " + lines.length + " 行）" : "";
  var isAi = pick.from === "ai";
  return '<div class="subConfirm">' +
    '<div class="subConfirmHead">确认提交<span class="subSrc' + (isAi ? " ai" : "") + '">将提交：' +
      escapeHtml(hwFromText(pick.from)) + "</span></div>" +
    (isAi ? '<p class="subWarn">这是 AI 写的代码 —— 交上去会算在你自己的 OJ 提交记录里。</p>' : "") +
    '<pre class="subPreview"><code>' + escapeHtml(head3 + more) + "</code></pre>" +
    '<p class="subNote">提交会出现在 OJ 的提交列表里，和你在网页上交一样 —— 包括可能的次数限制。</p>' +
    '<div class="subActions"><button class="primary" data-act="ojsubmit">确认提交</button>' +
    '<button data-act="ojsubcancel">取消</button></div>' +
  "</div>";
}
